// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type SlowLoadDemoProps = Record<string, any>;

const SlowLoadDemo: React.FC<SlowLoadDemoProps> = ({
  backgroundColor = "#0485B9",
  transparentBackground = false,
  durationInSeconds = 4,
  browserBgColor = "#FFFFFF",
  browserHeaderColor = "#E0E0E0",
  loadingBarColor = "#2196F3",
  scriptLabelBg = "#F0F0F0",
  scriptLabelText = "#333333",
  alertTextColor = "#FA762A",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Configuration & Timings
  const SCRIPT_APPEAR_START = 5;
  const SCRIPT_STAGGER = 4;
  const LOADING_BAR_START = 36; // 1.2s at 30fps
  const ALERT_START = 75; // 2.5s at 30fps

  const scriptNames = [
    "script.js",
    "tracker.js",
    "plugin.js",
    "analytics.js",
    "ads.js",
    "pixel.js",
    "widget.js",
    "chat.js",
    "auth.js",
    "core.js",
  ];

  // Browser Entrance Animation
  const browserScale = spring({
    fps,
    frame,
    config: { damping: 14, mass: 0.8 },
  });

  const browserOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Loading Bar Progress Logic
  // It starts filling normally, then slows down dramatically to simulate the effect of scripts
  const loadingProgress = interpolate(
    frame,
    [LOADING_BAR_START, LOADING_BAR_START + 15, ALERT_START, ALERT_START + 60],
    [0, 60, 85, 90], // Reaches 60% fast, then crawls to 85%, then barely moves
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.25, 0.1, 0.25, 1),
    }
  );

  // Alert Text Animation ("Slow load")
  const alertScale = spring({
    fps,
    frame: frame - ALERT_START,
    config: { damping: 10, mass: 0.6, stiffness: 150 },
  });

  const alertOpacity = interpolate(
    frame,
    [ALERT_START, ALERT_START + 10],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Responsive sizing
  const browserWidth = width * 0.75;
  const browserHeight = height * 0.35;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Scripts Area Above Browser */}
      <div
        style={{
          width: browserWidth,
          height: height * 0.2, // Fixed height to prevent layout shifts
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "flex-end",
          paddingBottom: 40,
        }}
      >
        <div
          style={{
            fontSize: 42,
            fontWeight: 600,
            color: "#FFFFFF",
            marginBottom: 24,
            opacity: browserOpacity,
            transform: `scale(${browserScale})`,
          }}
        >
          Scripts
        </div>
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: 16,
            justifyContent: "center",
            width: "100%",
          }}
        >
          {scriptNames.map((name, index) => {
            const appearFrame = SCRIPT_APPEAR_START + index * SCRIPT_STAGGER;
            const tagScale = spring({
              fps,
              frame: frame - appearFrame,
              config: { damping: 12 },
            });
            const tagOpacity = interpolate(
              frame,
              [appearFrame, appearFrame + 10],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            return (
              <div
                key={name}
                style={{
                  backgroundColor: scriptLabelBg,
                  color: scriptLabelText,
                  padding: "12px 20px",
                  borderRadius: 8,
                  fontSize: 24,
                  fontWeight: 500,
                  transform: `scale(${tagScale})`,
                  opacity: tagOpacity,
                  boxShadow: "0px 4px 12px rgba(0,0,0,0.1)",
                }}
              >
                {name}
              </div>
            );
          })}
        </div>
      </div>

      {/* Browser Window */}
      <div
        style={{
          width: browserWidth,
          height: browserHeight,
          backgroundColor: browserBgColor,
          borderRadius: 24,
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          boxShadow: "0px 24px 64px rgba(0,0,0,0.2)",
          transform: `scale(${browserScale})`,
          opacity: browserOpacity,
        }}
      >
        {/* Browser Top Bar */}
        <div
          style={{
            height: 60,
            backgroundColor: browserHeaderColor,
            position: "relative",
            display: "flex",
            alignItems: "center",
            padding: "0 24px",
            gap: 12,
          }}
        >
          {/* Fake Window Controls */}
          <div
            style={{
              width: 16,
              height: 16,
              borderRadius: "50%",
              backgroundColor: "#FF5F56",
            }}
          />
          <div
            style={{
              width: 16,
              height: 16,
              borderRadius: "50%",
              backgroundColor: "#FFBD2E",
            }}
          />
          <div
            style={{
              width: 16,
              height: 16,
              borderRadius: "50%",
              backgroundColor: "#27C93F",
            }}
          />
          
          {/* Progress Bar (Empty Background) */}
          <div
            style={{
              position: "absolute",
              bottom: 0,
              left: 0,
              right: 0,
              height: 8,
              backgroundColor: "rgba(0,0,0,0.05)",
            }}
          >
            {/* Filling Progress Bar */}
            <div
              style={{
                height: "100%",
                width: `${loadingProgress}%`,
                backgroundColor: loadingBarColor,
              }}
            />
          </div>
        </div>

        {/* Browser Content */}
        <div
          style={{
            flex: 1,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            position: "relative",
          }}
        >
          {/* Slow Load Text */}
          <div
            style={{
              color: alertTextColor,
              fontSize: 80,
              fontWeight: 800,
              transform: `scale(${alertScale})`,
              opacity: alertOpacity,
              textTransform: "uppercase",
              letterSpacing: 2,
            }}
          >
            Slow load
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SlowLoadDemo;